/** Athena's version from package.json, put in by the build (app/vite.config.ts `define`). */
declare const __ATHENA_VERSION__: string;
/** The commit the build was made from (Netlify's COMMIT_REF), or "" outside Netlify. */
declare const __ATHENA_COMMIT__: string;
/** When the build was made, as an ISO time. */
declare const __ATHENA_BUILT_AT__: string;
